import fs from "fs"; import {execSync} from "child_process";
for(let round=0;round<6;round++){
 let o=""; try{o=execSync("npx ngc -p tsconfig.json --noEmit 2>&1").toString();}catch(e){o=(e.stdout||"").toString()+(e.stderr||"").toString();}
 o=o.replace(/\x1b\[[0-9;]*m/g,"").replace(/\r/g,"");
 const errs=[...o.matchAll(/^(\S+?):(\d+):(\d+) - error TS(\d+): (.*)$/gm)];
 const rel=errs.filter(e=>/'disableTooltip' does not exist on type '(PillComponent|FancyPillComponent|StatusPillComponent)'/.test(e[5]));
 console.log("round",round,"errors",errs.length,"fixable",rel.length);
 if(!rel.length){ console.log(o.slice(0,3000)); break; }
 const by={}; for(const e of rel)(by[e[1]]??=[]).push([+e[2],+e[3]]);
 for(const f in by){ const lines=fs.readFileSync(f,"utf8").split("\n");
  const seen=new Set();
  for(const [l,c] of by[f].sort((a,b)=>b[0]-a[0]||b[1]-a[1])){ const k=l+":"+c; if(seen.has(k))continue; seen.add(k);
   const s=lines[l-1]; if(s.substr(c-1,14)==="disableTooltip") lines[l-1]=s.slice(0,c-1)+"hideHint"+s.slice(c+13); else console.log("MISMATCH",f,l,c,s); }
  fs.writeFileSync(f,lines.join("\n")); }
}

