input.command:
cat > /tmp/pillchk.mjs <<'EOF'
import fs from "fs"; import {execSync} from "child_process";
const files = execSync('git ls-files "src/*.ts" "src/*.html"').toString().trim().split("\n");
const cnt={};
for (const f of files){ const s=fs.readFileSync(f,"utf8");
 const re=/<(app-[a-z-]+)(?=[\s>\/])/g; let m;
 while((m=re.exec(s))){ let j=m.index+m[0].length,q=null;
  for(;j<s.length;j++){const c=s[j]; if(q){if(c===q)q=null;} else if(c==='"'||c==="'")q=c; else if(c==='>')break;}
  const tag=s.slice(m.index,j).replace(/"[^"]*"|'[^']*'/g,'""');
  for(const w of ["disableTooltip","hideHint"]) if(new RegExp("[\\s\\[]"+w+"[\\]\\s=/]|"+w+"$").test(tag)){const k=m[1]+" "+w;cnt[k]=(cnt[k]||0)+1;}
  re.lastIndex=j; } }
console.log(cnt);
EOF
node /tmp/pillchk.mjs; git diff --stat | tail -1; npx ngc -p tsconfig.json; echo exit $?

